<?php
require __DIR__.'/config/database.php';require __DIR__.'/includes/functions.php';require_admin();verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){$username=trim($_POST['username']??'');$nama=trim($_POST['nama']??'');$password=$_POST['password']??'';$level=$_POST['level']??'Siswa';if(!$username||!$nama||strlen($password)<4||!in_array($level,['Admin','Guru','Siswa'],true)){flash('Lengkapi data. Password minimal 4 karakter.','error');}else{try{$nis=($level==='Siswa'&&(int)($_POST['nis']??0)>0)?(int)$_POST['nis']:null;$st=$pdo->prepare('INSERT INTO users(username,password,nama,level,nis) VALUES(?,?,?,?,?)');$st->execute([$username,password_hash($password,PASSWORD_DEFAULT),$nama,$level,$nis]);flash('Pengguna berhasil dibuat. Password baru disimpan dalam bentuk hash.');}catch(Throwable $e){flash('Gagal membuat pengguna. Username mungkin sudah digunakan.','error');}}header('Location: pengguna.php');exit;}
$pageTitle='Pengguna';$students=$pdo->query('SELECT nis,nama,kelas FROM siswa ORDER BY nama')->fetchAll();$rows=$pdo->query('SELECT u.id_user,u.username,u.nama,u.level,s.nama AS siswa_nama,s.kelas FROM users u LEFT JOIN siswa s ON s.nis=u.nis ORDER BY u.id_user')->fetchAll();require __DIR__.'/includes/header.php';
?><div class="welcome-row"><div><span class="eyebrow">AKSES APLIKASI</span><h1>Pengguna</h1><p>Kelola akun yang dapat masuk ke EnergiLestari.</p></div></div><div class="content-split"><section class="panel form-panel"><div class="panel-heading"><div><h2>Buat akun baru</h2><p>Password disimpan menggunakan hash.</p></div></div><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><div class="form-field"><label>Nama lengkap</label><input class="form-control" name="nama" required></div><div class="form-field"><label>Username</label><input class="form-control" name="username" required></div><div class="form-field"><label>Password</label><input class="form-control" type="password" name="password" minlength="4" required></div><div class="form-field"><label>Peran</label><select class="form-control" name="level"><option>Siswa</option><option>Guru</option><option>Admin</option></select></div><div class="form-field"><label>Data siswa (khusus peran Siswa)</label><select class="form-control" name="nis"><option value="">— Tidak dihubungkan —</option><?php foreach($students as $s): ?><option value="<?= (int)$s['nis'] ?>"><?= e($s['nama'].' — '.$s['kelas']) ?></option><?php endforeach; ?></select></div><button class="btn btn-primary btn-full">Buat Pengguna</button></form></section><section class="panel table-panel"><div class="panel-heading"><div><h2>Daftar akun</h2><p><?= count($rows) ?> akun tersedia.</p></div></div><div class="table-wrap"><table><thead><tr><th>Pengguna</th><th>Username</th><th>Level</th><th>Data siswa</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><div class="table-person"><span class="avatar avatar-small"><?= e(strtoupper(substr($r['nama'],0,1))) ?></span><b><?= e($r['nama']) ?></b></div></td><td><?= e($r['username']) ?></td><td><span class="status-pill"><?= e($r['level']) ?></span></td><td><?= $r['siswa_nama']?e($r['siswa_nama'].' — '.$r['kelas']):'-' ?></td></tr><?php endforeach; ?></tbody></table></div></section></div><?php require __DIR__.'/includes/footer.php'; ?>
